package local.tv.launcher;
import android.content.Context;
import org.json.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
/** User-entered city only; never obtains device location. Blocking background API. */
public final class WeatherClient {
 private final CatalogClient.Cache cache;
 public WeatherClient(Context c){cache=new CatalogClient.Cache(c,"weather_metadata",1024*1024);}
 private JSONObject get(String url)throws Exception{return new JSONObject(new String(SecureHttp.get(url,Collections.emptyMap(),1024*1024),StandardCharsets.UTF_8));}
 public synchronized JSONObject load(String city){String name=NetworkPolicy.query(city);if(name.isEmpty())name="Pune";String key="city:"+name;JSONObject saved=cache.read(key);if(saved!=null&&cache.fresh(key,15*60*1000))return mark(saved,"cached",false);try{JSONObject geo=get("https://geocoding-api.open-meteo.com/v1/search?name="+URLEncoder.encode(name,"UTF-8")+"&count=1&language=en&format=json");JSONArray results=geo.optJSONArray("results");if(results==null||results.length()==0)throw new IllegalArgumentException();JSONObject place=results.getJSONObject(0);double lat=place.getDouble("latitude"),lon=place.getDouble("longitude");if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new IllegalArgumentException();JSONObject forecast=get("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,weather_code&temperature_unit=celsius&timezone=auto");JSONObject current=forecast.getJSONObject("current");double temp=current.getDouble("temperature_2m");int code=current.getInt("weather_code");if(!Double.isFinite(temp)||!current.has("time"))throw new IllegalArgumentException();String[] condition=condition(code);JSONObject value=new JSONObject().put("available",true).put("temp",temp).put("condition",condition[0]).put("icon",condition[1]).put("city",place.optString("name",name)).put("updated",current.getString("time")).put("timezone",forecast.optString("timezone","")).put("status","live").put("stale",false).put("message","");cache.write(key,value);return value;}catch(Exception ignored){if(saved!=null)return mark(saved,"cached",true);JSONObject unavailable=new JSONObject();try{unavailable.put("available",false).put("temp",JSONObject.NULL).put("condition","Unavailable").put("icon","").put("city",name).put("updated","").put("status","error").put("message","Weather unavailable").put("stale",false);}catch(JSONException impossible){}return unavailable;}}
 private JSONObject mark(JSONObject value,String status,boolean stale){try{value.put("status",status).put("stale",stale).put("message",stale?"Offline: previously fetched weather":"Cached within 15 minutes");}catch(JSONException ignored){}return value;}
 static String[] condition(int code){if(code==0)return new String[]{"Clear","sun"};if(code>=1&&code<=3)return new String[]{code==3?"Overcast":"Partly cloudy","cloud"};if(code==45||code==48)return new String[]{"Fog","fog"};if(code>=51&&code<=57)return new String[]{"Drizzle","rain"};if((code>=61&&code<=67)||(code>=80&&code<=82))return new String[]{"Rain","rain"};if((code>=71&&code<=77)||code==85||code==86)return new String[]{"Snow","snow"};if(code==95||code==96||code==99)return new String[]{"Thunderstorm","storm"};return new String[]{"Unknown conditions","cloud"};}
}
